function receipt = f90_xbatt02_measurement(modelPath,outDir)
%F90_XBATT02_CANDIDATE_SIMULATION_CORE Dedicated multi-scenario physical scorer.
%
% Outputs are identified by their public Timeseries contract.  The scorer
% validates actual signal connections and cross-domain behavior rather than
% recognizing block names.  Required multi-condition performance is reduced
% by the worst applicable official scenario.
arguments
    modelPath (1,1) string = ...
        fullfile(getenv("SIMUVERITY_TASK_ROOT"), "reference", "files", "XBATT02_reference.slx")
    outDir (1,1) string = ...
        tempdir
end

repoRoot = fullfile(getenv("SIMUVERITY_TASK_VENDOR_ROOT"));
taskCode = fileparts(mfilename("fullpath"));
if ~isfolder(outDir), mkdir(outDir); end
addpath(taskCode,"-begin");
addpath(fullfile(repoRoot,"scripts","xp9"),"-end");
def = f90_xbatt02_definition;
receipt = empty_receipt(def,modelPath);

inputNames = string({def.public_inputs.name});
baseSnapshot = snapshot_base(inputNames);
baseCleanup = onCleanup(@() restore_base(baseSnapshot)); %#ok<NASGU>

try
    assert(isfile(modelPath),"F90_XBATT02_MODEL_NOT_FOUND");
    receipt.model_file_presence = xp9_file_presence_file(modelPath);
    nominal = nominal_values(def);
    set_base(nominal);
    [~,model] = fileparts(modelPath);
    model = string(model);
    if bdIsLoaded(model), close_system(model,0); end
    load_system(modelPath);
    modelCleanup = onCleanup(@() close_model(model)); %#ok<NASGU>
    receipt.load_pass = true;
    receipt.static_audit = static_audit(model,def);

    set_param(model,"SimulationCommand","update");
    receipt.update_pass = true;
    feval(model,[],[],[],"compile");
    feval(model,[],[],[],"term");
    receipt.compile_pass = true;

    scenarioDefs = [ ...
        struct("id","nominal","values",nominal),def.scenarios];
    runs = repmat(empty_run,1,numel(scenarioDefs));
    rows = repmat(empty_row,1,numel(scenarioDefs));
    for index = 1:numel(scenarioDefs)
        runs(index) = run_scenario(model,scenarioDefs(index),def);
        rows(index) = measure_run(runs(index),def);
    end
    receipt.scenario_rows = rows;
    [suite,pairs] = measure_suite(rows,def);
    receipt.metric_values = struct( ...
        "physical_suite",suite, ...
        "causal_pairs",pairs);

    G = receipt.load_pass && receipt.update_pass && ...
        receipt.compile_pass && all([rows.valid]) && ...
        receipt.static_audit.output_contract_connected && ...
        receipt.static_audit.precomputed_direct_output_count == 0 && ...
        receipt.static_audit.suspicious_callback_count == 0 && ...
        receipt.static_audit.dynamic_state_evidence;
    groups = compute_groups(rows,suite,pairs, ...
        receipt.static_audit,def,G);
    receipt.groups = groups;
    receipt.valid = G;
    receipt.failure_reasons = failure_reasons( ...
        rows,suite,pairs,receipt.static_audit,G);

    weights = def.groups.weights;
    total = 100*(weights.A*groups.A + weights.Q*groups.Q + ...
        weights.M*groups.M + weights.R*groups.R + ...
        weights.D*groups.D);
    if ~G, total = 0; end
    validRows = rows([rows.valid]);
    if ~isempty(validRows)
        safetyViolation = ...
            max([validRows.peak_temperature_K]) > 318.01 || ...
            max([validRows.temperature_spread_K]) > 5.01 || ...
            min([validRows.minimum_soc]) < .0795 || ...
            min([validRows.minimum_cell_voltage_V]) < 2.749 || ...
            max([validRows.pump_power_max_W]) > 500.5 || ...
            max([validRows.branch_flow_max_kg_per_s]) > .0601 || ...
            min([validRows.branch_flow_min_kg_per_s]) < -1e-5;
    end
    receipt.total = min(max(double(total),0),100);
catch scorerError
    receipt.valid = false;
    receipt.total = 0;
    receipt.groups = zero_groups;
    receipt.failure_reasons = unique([receipt.failure_reasons; ...
        "SCORER_EXCEPTION:" + string(scorerError.identifier) + ...
        ":" + string(scorerError.message)],"stable");
    receipt.error_identifier = string(scorerError.identifier);
    receipt.error_message = string(scorerError.message);
end

receipt.finished_at = timestamp;
receipt.score = receipt.total;
receipt.G = logical(receipt.groups.G);
receipt.score_inputs_valid = receipt.valid;
receipt.runtime_identity = struct( ...
    "generation_run_id",string(getenv("SIMUVERITY_GENERATION_RUN_ID")), ...
    "lane",string(getenv("SIMUVERITY_MATLAB_LANE")), ...
    "workspace",string(getenv("SIMUVERITY_WORKSPACE")), ...
    "matlab_prefdir",string(getenv("MATLAB_PREFDIR")), ...
    "appdata",string(getenv("APPDATA")), ...
    "localappdata",string(getenv("LOCALAPPDATA")), ...
    "temp",string(getenv("TEMP")), ...
    "mcp_port",string(getenv("SIMUVERITY_MCP_PORT")), ...
    "matlab_release",string(version("-release")));
write_json(fullfile(outDir,"receipt.json"),receipt);
fprintf("F90_XBATT02_SCORE valid=%d total=%.6f out=%s\n", ...
    receipt.valid,receipt.total,outDir);
end

function run = run_scenario(model,scenario,def)
run = empty_run;
run.id = string(scenario.id);
run.inputs = scenario.values;
try
    set_base(run.inputs);
    input = Simulink.SimulationInput(model);
    names = fieldnames(run.inputs);
    for index = 1:numel(names)
        input = input.setVariable(names{index}, ...
            run.inputs.(names{index}),"Workspace",model);
    end
    input = input.setModelParameter( ...
        "StopTime",num2str(def.sim.stop,17), ...
        "ReturnWorkspaceOutputs","on");
    output = sim(input);
    outputNames = string({def.outputs.name});
    data = cell(1,numel(outputNames));
    times = cell(1,numel(outputNames));
    shapes = struct;
    for index = 1:numel(outputNames)
        value = output.get(outputNames(index));
        assert(isa(value,"timeseries"), ...
            "F90_XBATT02_OUTPUT_NOT_TIMESERIES:%s", ...
            outputNames(index));
        times{index} = double(value.Time(:));
        [data{index},rawSize,timeDimension] = ...
            normalize_data(value,times{index}, ...
            def.outputs(index).channels);
        assert(size(data{index},2) == def.outputs(index).channels, ...
            "F90_XBATT02_CHANNEL_COUNT:%s",outputNames(index));
        assert(all(isfinite(data{index}),"all") && ...
            all(isfinite(times{index})), ...
            "F90_XBATT02_NONFINITE:%s",outputNames(index));
        assert(isreal(data{index}), ...
            "F90_XBATT02_COMPLEX_OUTPUT:%s",outputNames(index));
        shapes.(outputNames(index)) = struct( ...
            "raw_size",rawSize, ...
            "time_dimension",timeDimension, ...
            "channels",size(data{index},2), ...
            "samples",numel(times{index}));
    end
    time = times{1};
    assert(~isempty(time) && all(diff(time) > 0), ...
        "F90_XBATT02_BAD_TIME");
    for index = 2:numel(times)
        assert(numel(times{index}) == numel(time) && ...
            max(abs(times{index}-time)) <= 1e-9, ...
            "F90_XBATT02_TIME_MISMATCH:%s",outputNames(index));
    end
    assert(time(1) <= 1e-9 && ...
        time(end) >= def.sim.stop-1e-9, ...
        "F90_XBATT02_TIME_COVERAGE");
    run.time = time;
    run.pack = data{1};
    run.modules = data{2};
    run.cooling = data{3};
    run.flux = data{4};
    run.output_shapes = shapes;
    run.valid = true;
catch scenarioError
    run.error = string(scenarioError.identifier) + ...
        ":" + string(scenarioError.message);
end
end

function row = measure_run(run,def)
row = empty_row;
row.id = run.id;
if ~run.valid
    row.error = run.error;
    return
end

t = run.time;
pack = run.pack;
modules = run.modules;
cooling = run.cooling;
flux = run.flux;
values = run.inputs;
ns = double(def.public_constants.module_series_cell_counts);
cth = double(def.public_constants.module_thermal_capacities_J_per_K);
cp = double(def.public_constants.coolant_specific_heat_J_per_kgK);
capacityC = double(def.public_constants.parallel_cells_per_module) * ...
    double(def.public_constants.cell_capacity_Ah) * 3600;

requested = pack(:,1);
delivered = pack(:,2);
pumpCurrent = pack(:,3);
packCurrent = pack(:,4);
packVoltage = pack(:,5);
reportedMinSoc = pack(:,6);
reportedMaxTemp = pack(:,7);
limitingFlag = pack(:,8);
moduleVoltage = modules(:,1:8);
moduleSoc = modules(:,9:16);
moduleTemp = modules(:,17:24);
pumpCommand = cooling(:,1);
pumpPower = cooling(:,2);
inletTemp = cooling(:,3);
branchFlow = cooling(:,4:11);
outletTemp = cooling(:,12:19);
qGeneration = flux(:,1:8);
qCooling = flux(:,9:16);
perCellVoltage = moduleVoltage./ns;

expectedRequest = request_profile(t,values,def);
positiveRequest = expectedRequest > 1;
notLimited = positiveRequest & limitingFlag < .5;
if nnz(notLimited) < 20, notLimited = positiveRequest; end
regen = t >= double(values.regen_start_time) & ...
    t < double(values.regen_start_time) + ...
    double(def.public_constants.regen_duration_s);

row.samples = numel(t);
row.request_nrmse = local_rms(requested-expectedRequest) / ...
    max(double(values.current_demand),1);
row.delivery_nrmse = local_rms( ...
    delivered(notLimited)-expectedRequest(notLimited)) / ...
    max(double(values.current_demand),1);
row.peak_temperature_K = max(moduleTemp,[],"all");
row.temperature_spread_K = max( ...
    max(moduleTemp,[],2)-min(moduleTemp,[],2));
row.minimum_soc = min(moduleSoc,[],"all");
row.minimum_cell_voltage_V = min( ...
    moduleVoltage./ns,[],"all");
row.pump_command_min = min(pumpCommand);
row.pump_command_max = max(pumpCommand);
row.pump_power_min_W = min(pumpPower);
row.pump_power_max_W = max(pumpPower);
row.branch_flow_min_kg_per_s = min(branchFlow,[],"all");
row.branch_flow_max_kg_per_s = max(branchFlow,[],"all");
row.flow_spread_mean_kg_per_s = mean( ...
    max(branchFlow,[],2)-min(branchFlow,[],2));
row.final_temperature_spread_K = ...
    max(moduleTemp(end,:))-min(moduleTemp(end,:));

attenuated = positiveRequest & ...
    delivered < .999*max(expectedRequest,1);
row.limiter_consistency_error = mean(abs( ...
    double(limitingFlag > .5)-double(attenuated)));
row.limiter_fraction = mean(limitingFlag(positiveRequest) > .5);
attenuationTrace = max(expectedRequest-delivered,0) ./ ...
    max(abs(expectedRequest),1);
row.attenuation_fraction = mean( ...
    attenuationTrace(positiveRequest));
riskTrace = max([ ...
    clip_vector((.13-min(moduleSoc,[],2))/.05), ...
    clip_vector((2.90-min(perCellVoltage,[],2))/.15), ...
    clip_vector((max(moduleTemp,[],2)-314)/4)],[],2);
row.risk_attenuation_correlation = positive_correlation( ...
    riskTrace(positiveRequest),attenuationTrace(positiveRequest));
lowRisk = positiveRequest & riskTrace < .15;
highRisk = positiveRequest & riskTrace > .35;
if nnz(lowRisk) >= 20 && nnz(highRisk) >= 20
    row.risk_attenuation_gain = ...
        mean(attenuationTrace(highRisk))- ...
        mean(attenuationTrace(lowRisk));
else
    row.risk_attenuation_gain = 0;
end
firstLimit = find(limitingFlag > .5 & positiveRequest,1);
if ~isempty(firstLimit)
    row.post_limit_soc_change = abs( ...
        mean(moduleSoc(end,:))-mean(moduleSoc(firstLimit,:)));
else
    row.post_limit_soc_change = 0;
end

row.current_closure_error = local_rms( ...
    packCurrent-delivered-pumpCurrent) / ...
    max(local_rms(packCurrent),1);
row.voltage_closure_error = local_rms( ...
    packVoltage-sum(moduleVoltage,2)) / ...
    max(local_rms(packVoltage),10);
row.pump_auxiliary_closure_error = local_rms( ...
    pumpPower-packVoltage.*pumpCurrent) / ...
    max(local_rms(pumpPower),20);
row.reported_min_soc_error = local_rms( ...
    reportedMinSoc-min(moduleSoc,[],2));
row.reported_max_temperature_error_K = local_rms( ...
    reportedMaxTemp-max(moduleTemp,[],2));

dt = diff(t);
actualSocRate = diff(moduleSoc,1,1)./dt;
expectedSocRateLeft = -packCurrent(1:end-1)/capacityC;
expectedSocRateTrap = -.5*( ...
    packCurrent(1:end-1)+packCurrent(2:end))/capacityC;
leftCoulombError = local_rms( ...
    actualSocRate-expectedSocRateLeft);
trapCoulombError = local_rms( ...
    actualSocRate-expectedSocRateTrap);
row.coulomb_balance_error = min( ...
    leftCoulombError,trapCoulombError) / ...
    max(local_rms(expectedSocRateLeft),1e-6);

row.per_cell_voltage_spread = mean( ...
    std(perCellVoltage,0,2) ./ ...
    max(abs(mean(perCellVoltage,2)),1));
rawTwelve = mean(moduleVoltage(:,[1:3 6:8]),2);
rawSixteen = mean(moduleVoltage(:,4:5),2);
row.mixed_geometry_ratio_error = mean(abs( ...
    rawSixteen./max(abs(rawTwelve),1) - 16/12)) / (16/12);

[leftThermalError,leftConductance] = thermal_fit( ...
    moduleTemp(1:end-1,:), ...
    qGeneration(1:end-1,:), ...
    qCooling(1:end-1,:), ...
    diff(moduleTemp,1,1)./dt, ...
    double(values.ambient_temperature),cth);
[trapThermalError,trapConductance] = thermal_fit( ...
    .5*(moduleTemp(1:end-1,:)+moduleTemp(2:end,:)), ...
    .5*(qGeneration(1:end-1,:)+qGeneration(2:end,:)), ...
    .5*(qCooling(1:end-1,:)+qCooling(2:end,:)), ...
    diff(moduleTemp,1,1)./dt, ...
    double(values.ambient_temperature),cth);
if leftThermalError <= trapThermalError
    row.thermal_balance_error = leftThermalError;
    row.fitted_ambient_conductance_min_W_per_K = ...
        min(leftConductance);
else
    row.thermal_balance_error = trapThermalError;
    row.fitted_ambient_conductance_min_W_per_K = ...
        min(trapConductance);
end

expectedCooling = branchFlow*cp.* ...
    (outletTemp-inletTemp);
row.coolant_enthalpy_error = local_rms( ...
    qCooling-expectedCooling) / ...
    max(local_rms(qCooling),10);
passiveViolation = qCooling < -1 | ...
    outletTemp < inletTemp-.5 | ...
    outletTemp > moduleTemp+.5;
row.coolant_passivity_error = mean(passiveViolation,"all");

currentSquared = packCurrent.^2;
meanHeat = mean(qGeneration,2);
row.heat_current_correlation = ...
    positive_correlation(currentSquared,meanHeat);
thermalDrive = max(moduleTemp,[],2)-inletTemp;
row.pump_thermal_correlation = ...
    positive_correlation(thermalDrive,pumpCommand);
coolingDrive = branchFlow.*max(moduleTemp-inletTemp,0);
row.cooling_path_correlation = ...
    positive_correlation(coolingDrive(:),qCooling(:));

stepTime = double(values.load_step_time);
early = t >= stepTime+.25 & t <= stepTime+1.5;
late = t >= stepTime+8 & t <= stepTime+15;
if nnz(early) >= 3 && nnz(late) >= 3
    row.polarization_drop_per_cell_V = max( ...
        mean(perCellVoltage(early,:),"all") - ...
        mean(perCellVoltage(late,:),"all"),0);
end

row.current_rms_A = local_rms(packCurrent);
row.mean_heat_generation_W = mean(qGeneration,"all");
row.soc_depletion = max( ...
    mean(moduleSoc(1,:))-mean(moduleSoc(end,:)),0);
row.temperature_rise_K = max(moduleTemp,[],"all") - ...
    mean(moduleTemp(1,:));
row.mean_pump_power_W = mean(pumpPower);
row.mean_branch_flow_kg_per_s = mean(branchFlow,"all");
row.mean_cooling_power_W = mean(qCooling,"all");
flowCv = std(branchFlow,0,2) ./ ...
    max(abs(mean(branchFlow,2)),1e-6);
row.flow_cv_mean = mean(flowCv);
if nnz(regen) >= 3
    row.regen_current_fraction = mean(delivered(regen) < ...
        -.1*double(values.current_demand));
    regenSoc = mean(moduleSoc(regen,:),2);
    row.regen_soc_gain = regenSoc(end)-regenSoc(1);
    preRegen = t >= double(values.regen_start_time)-2 & ...
        t < double(values.regen_start_time)-.1;
    earlyRegen = t >= double(values.regen_start_time)+.5 & ...
        t <= double(values.regen_start_time)+2;
    if nnz(preRegen) >= 3 && nnz(earlyRegen) >= 3
        row.regen_voltage_rise_per_cell_V = ...
            mean(perCellVoltage(earlyRegen,:),"all") - ...
            mean(perCellVoltage(preRegen,:),"all");
    end
end

initialSocError = max(abs( ...
    moduleSoc(1,:)-double(values.initial_soc)));
broadDomain = all(packCurrent > -1000 & packCurrent < 1000) && ...
    all(packVoltage > 50 & packVoltage < 1000) && ...
    all(moduleVoltage > 1 & moduleVoltage < 100,"all") && ...
    all(moduleSoc > -.02 & moduleSoc < 1.02,"all") && ...
    all(moduleTemp > 240 & moduleTemp < 380,"all") && ...
    all(pumpCommand > -1 & pumpCommand < 2) && ...
    all(pumpPower > -100 & pumpPower < 5000) && ...
    all(branchFlow > -.01 & branchFlow < .15,"all") && ...
    all(limitingFlag > -.05 & limitingFlag < 1.05) && ...
    all(abs(qGeneration) < 1e7,"all") && ...
    all(abs(qCooling) < 1e7,"all") && ...
    initialSocError <= .05;
allMetrics = struct_numeric(row);
row.valid = broadDomain && all(isfinite(allMetrics));
if ~row.valid
    row.error = "PHYSICAL_OR_OUTPUT_DOMAIN_INVALID";
end
end

function [suite,pairs] = measure_suite(rows,def)
validRows = rows([rows.valid]);
suite = empty_suite;
if isempty(validRows), pairs = empty_pairs; return; end

suite.request_contract_worst = max([validRows.request_nrmse]);
suite.current_closure_worst = max([validRows.current_closure_error]);
suite.voltage_closure_worst = max([validRows.voltage_closure_error]);
suite.pump_auxiliary_closure_worst = ...
    max([validRows.pump_auxiliary_closure_error]);
suite.reported_state_worst = max([ ...
    [validRows.reported_min_soc_error], ...
    [validRows.reported_max_temperature_error_K]/10]);
suite.coulomb_balance_worst = max([validRows.coulomb_balance_error]);
suite.per_cell_voltage_spread_worst = ...
    max([validRows.per_cell_voltage_spread]);
suite.mixed_geometry_ratio_worst = ...
    max([validRows.mixed_geometry_ratio_error]);
suite.polarization_drop_min_V = ...
    min([validRows.polarization_drop_per_cell_V]);
suite.heat_current_correlation_min = ...
    min([validRows.heat_current_correlation]);
suite.thermal_balance_worst = max([validRows.thermal_balance_error]);
suite.coolant_enthalpy_worst = max([validRows.coolant_enthalpy_error]);
suite.coolant_passivity_worst = max([validRows.coolant_passivity_error]);
suite.pump_thermal_correlation_min = ...
    min([validRows.pump_thermal_correlation]);
suite.cooling_path_correlation_min = ...
    min([validRows.cooling_path_correlation]);

pairs = empty_pairs;
lowDemand = row_by_id(rows,"demand_pair_low");
highDemand = row_by_id(rows,"demand_pair_high");
if lowDemand.valid && highDemand.valid
    currentRatio = highDemand.current_rms_A / ...
        max(lowDemand.current_rms_A,1);
    heatRatio = highDemand.mean_heat_generation_W / ...
        max(lowDemand.mean_heat_generation_W,1);
    depletionRatio = highDemand.soc_depletion / ...
        max(lowDemand.soc_depletion,1e-4);
    temperatureRiseDelta = highDemand.temperature_rise_K - ...
        lowDemand.temperature_rise_K;
    coolingRatio = highDemand.mean_cooling_power_W / ...
        max(lowDemand.mean_cooling_power_W,1);
    directionScores = [ ...
        quality_high(currentRatio,1.75,1.10), ...
        quality_high(heatRatio,2.5,1.10), ...
        quality_high(depletionRatio,1.75,1.05), ...
        quality_high(temperatureRiseDelta,.35,.02), ...
        quality_high(coolingRatio,1.5,1.02)];
    pairs.demand = struct( ...
        "current_ratio",currentRatio, ...
        "heat_ratio",heatRatio, ...
        "soc_depletion_ratio",depletionRatio, ...
        "temperature_rise_delta_K",temperatureRiseDelta, ...
        "cooling_power_ratio",coolingRatio, ...
        "direction_scores",directionScores, ...
        "score",min(directionScores));
end

lowFlow = row_by_id(rows,"maldistribution_pair_low");
highFlow = row_by_id(rows,"maldistribution_pair_high");
if lowFlow.valid && highFlow.valid
    flowCvDelta = highFlow.flow_cv_mean - lowFlow.flow_cv_mean;
    thermalDelta = highFlow.temperature_spread_K - ...
        lowFlow.temperature_spread_K;
    directionScores = [ ...
        quality_high(flowCvDelta,.10,.02), ...
        quality_high(thermalDelta,.50,.05)];
    pairs.maldistribution = struct( ...
        "flow_cv_delta",flowCvDelta, ...
        "temperature_spread_delta_K",thermalDelta, ...
        "direction_scores",directionScores, ...
        "score",min(directionScores));
end

dynamicMask = ismember(string({rows.id}), ...
    def.dynamic_scenario_ids);
dynamicRows = rows(dynamicMask & [rows.valid]);
if ~isempty(dynamicRows)
    regenFraction = min([dynamicRows.regen_current_fraction]);
    regenGain = min([dynamicRows.regen_soc_gain]);
    regenVoltageRise = min( ...
        [dynamicRows.regen_voltage_rise_per_cell_V]);
    pairs.regeneration = struct( ...
        "minimum_negative_current_fraction",regenFraction, ...
        "minimum_soc_gain",regenGain, ...
        "minimum_voltage_rise_per_cell_V",regenVoltageRise, ...
        "score",min([ ...
        quality_high(regenFraction,.95,.25), ...
        quality_high(regenGain,.003,.0002), ...
        quality_high(regenVoltageRise,.12,.02)]));
end

lowSoc = row_by_id(rows,"low_soc_supervision");
if lowSoc.valid
    boundaryScore = quality_high(lowSoc.minimum_soc,.080,.055);
    attenuationScore = quality_high( ...
        lowSoc.attenuation_fraction,.08,.005);
    limiterScore = quality( ...
        lowSoc.limiter_consistency_error,.03,.30);
    riskScore = min([ ...
        quality_high(lowSoc.risk_attenuation_gain,.12,.03), ...
        quality_high( ...
        lowSoc.risk_attenuation_correlation,.30,.05)]);
    dynamicStateScore = quality_high( ...
        lowSoc.post_limit_soc_change,.01,.0005);
    pairs.low_soc_supervision = struct( ...
        "minimum_soc",lowSoc.minimum_soc, ...
        "attenuation_fraction",lowSoc.attenuation_fraction, ...
        "limiter_consistency_error", ...
            lowSoc.limiter_consistency_error, ...
        "risk_attenuation_correlation", ...
            lowSoc.risk_attenuation_correlation, ...
        "risk_attenuation_gain", ...
            lowSoc.risk_attenuation_gain, ...
        "post_limit_soc_change",lowSoc.post_limit_soc_change, ...
        "score",min([boundaryScore,attenuationScore, ...
        limiterScore,riskScore,dynamicStateScore]));
end

if ~isempty(dynamicRows)
    minimumPumpResponse = min( ...
        [dynamicRows.pump_thermal_correlation]);
    minimumCoolingPath = min( ...
        [dynamicRows.cooling_path_correlation]);
    pairs.cooling_chain = struct( ...
        "minimum_pump_thermal_correlation",minimumPumpResponse, ...
        "minimum_flow_heat_correlation",minimumCoolingPath, ...
        "score",min([ ...
        quality_high(minimumPumpResponse,.75,.10), ...
        quality_high(minimumCoolingPath,.85,.20)]));
end
end

function groups = compute_groups(rows,suite,pairs,static,def,G)
groups = zero_groups;
groups.G = double(G);
if ~G, return; end

nominal = row_by_id(rows,"nominal");
groups.A = clip( ...
    .35*quality(nominal.delivery_nrmse,.02,.14) + ...
    .20*quality(nominal.peak_temperature_K,314.5,318.5) + ...
    .15*quality(nominal.temperature_spread_K,2.0,5.0) + ...
    .15*quality_high(nominal.minimum_soc,.16,.08) + ...
    .15*quality_high(nominal.minimum_cell_voltage_V,3.00,2.75));

validRows = rows([rows.valid]);
worstTemperature = max([validRows.peak_temperature_K]);
worstSpread = max([validRows.temperature_spread_K]);
worstSoc = min([validRows.minimum_soc]);
worstVoltage = min([validRows.minimum_cell_voltage_V]);
ratingViolation = max([ ...
    max([validRows.pump_command_max])-1, ...
    -min([validRows.pump_command_min]), ...
    (max([validRows.pump_power_max_W])-500)/500, ...
    -min([validRows.pump_power_min_W])/500, ...
    (max([validRows.branch_flow_max_kg_per_s])-.06)/.06, ...
    -min([validRows.branch_flow_min_kg_per_s])/.06,0]);
limiterError = max([validRows.limiter_consistency_error]);
safetyQualities = [ ...
    quality(worstTemperature,318,321), ...
    quality(worstSpread,5,8), ...
    quality_high(worstSoc,.08,.04), ...
    quality_high(worstVoltage,2.75,2.45), ...
    quality(ratingViolation,0,.10)];
groups.Q = clip(.65*min(safetyQualities) + ...
    .35*(.20*sum(safetyQualities) + ...
    quality(limiterError,.04,.28))/2);

staticScore = .55*double(static.dynamic_state_evidence) + ...
    .45*double(static.output_contract_connected && ...
    static.precomputed_direct_output_count == 0);
coreQualities = [ ...
    quality(suite.current_closure_worst,.005,.12), ...
    quality(suite.voltage_closure_worst,.001,.03), ...
    quality(suite.pump_auxiliary_closure_worst,.005,.12), ...
    quality(suite.coulomb_balance_worst,.025,.16), ...
    quality(suite.thermal_balance_worst,.06,.35), ...
    quality(suite.coolant_enthalpy_worst,.01,.15)];
weightedMechanism = clip( ...
    .06*quality(suite.request_contract_worst,.005,.06) + ...
    .08*quality(suite.current_closure_worst,.005,.12) + ...
    .07*quality(suite.voltage_closure_worst,.001,.03) + ...
    .07*quality(suite.pump_auxiliary_closure_worst,.005,.12) + ...
    .05*quality(suite.reported_state_worst,.002,.04) + ...
    .10*quality(suite.coulomb_balance_worst,.025,.16) + ...
    .06*quality(suite.per_cell_voltage_spread_worst,.03,.13) + ...
    .05*quality(suite.mixed_geometry_ratio_worst,.02,.10) + ...
    .06*quality_high(suite.polarization_drop_min_V,.006,.0004) + ...
    .07*quality_high(suite.heat_current_correlation_min,.85,.25) + ...
    .11*quality(suite.thermal_balance_worst,.06,.35) + ...
    .08*quality(suite.coolant_enthalpy_worst,.01,.15) + ...
    .04*quality(suite.coolant_passivity_worst,0,.10) + ...
    .05*quality_high(suite.pump_thermal_correlation_min,.75,.10) + ...
    .02*quality_high(suite.cooling_path_correlation_min,.85,.20) + ...
    .03*staticScore);
groups.M = min(weightedMechanism,.40+.60*min(coreQualities));

rangeMask = ismember(string({rows.id}),def.range_scenario_ids);
rangeRows = rows(rangeMask);
rangeScores = zeros(1,numel(rangeRows));
for index = 1:numel(rangeRows)
    row = rangeRows(index);
    rangeScores(index) = clip( ...
        .20*quality(row.peak_temperature_K,318,321) + ...
        .16*quality(row.temperature_spread_K,5,8) + ...
        .18*quality_high(row.minimum_soc,.08,.04) + ...
        .18*quality_high(row.minimum_cell_voltage_V,2.75,2.45) + ...
        .14*quality(row.delivery_nrmse,.04,.22) + ...
        .14*quality(row.limiter_consistency_error,.04,.30));
end
groups.R = min(rangeScores);

dynamicScores = [ ...
    pairs.demand.score, ...
    pairs.maldistribution.score, ...
    pairs.regeneration.score, ...
    pairs.low_soc_supervision.score, ...
    pairs.cooling_chain.score];
groups.D = clip(.75*min(dynamicScores)+.25*mean(dynamicScores));
end

function reasons = failure_reasons(rows,suite,pairs,static,G)
reasons = strings(0,1);
invalid = rows(~[rows.valid]);
for index = 1:numel(invalid)
    reasons(end+1,1) = "SCENARIO_" + invalid(index).id + ...
        ":" + invalid(index).error; %#ok<AGROW>
end
if ~static.output_contract_connected
    reasons(end+1,1) = "OUTPUT_CONTRACT_NOT_CONNECTED";
end
if static.precomputed_direct_output_count > 0
    reasons(end+1,1) = "DIRECT_PRECOMPUTED_OUTPUT_SOURCE";
end
if static.suspicious_callback_count > 0
    reasons(end+1,1) = "MODEL_CALLBACK_OUTPUT_INJECTION_RISK";
end
if ~static.dynamic_state_evidence
    reasons(end+1,1) = "NO_DYNAMIC_STATE_EVIDENCE";
end
if suite.current_closure_worst > .12
    reasons(end+1,1) = "PACK_CURRENT_CLOSURE_FAILED";
end
if suite.voltage_closure_worst > .03
    reasons(end+1,1) = "PACK_VOLTAGE_CLOSURE_FAILED";
end
if suite.pump_auxiliary_closure_worst > .12
    reasons(end+1,1) = "PUMP_AUXILIARY_NOT_CLOSED_TO_PACK";
end
if suite.coulomb_balance_worst > .16
    reasons(end+1,1) = "SOC_COULOMB_BALANCE_FAILED";
end
if suite.thermal_balance_worst > .35
    reasons(end+1,1) = "MODULE_THERMAL_BALANCE_FAILED";
end
if suite.coolant_enthalpy_worst > .15
    reasons(end+1,1) = "COOLANT_ENTHALPY_CLOSURE_FAILED";
end
if suite.polarization_drop_min_V < .0004
    reasons(end+1,1) = "FINITE_POLARIZATION_RESPONSE_FAILED";
end
if pairs.demand.score < .25
    reasons(end+1,1) = "DEMAND_PAIR_CAUSALITY_FAILED";
end
if pairs.maldistribution.score < .20
    reasons(end+1,1) = "MALDISTRIBUTION_PAIR_CAUSALITY_FAILED";
end
if pairs.regeneration.score < .25
    reasons(end+1,1) = "REGENERATION_RESPONSE_FAILED";
end
if pairs.low_soc_supervision.score < .25
    reasons(end+1,1) = "LOW_SOC_SUPERVISION_FAILED";
end
if pairs.cooling_chain.score < .25
    reasons(end+1,1) = "CLOSED_LOOP_COOLING_CHAIN_FAILED";
end
validRows = rows([rows.valid]);
if ~isempty(validRows)
    if max([validRows.peak_temperature_K]) > 318.01
        reasons(end+1,1) = "PUBLIC_TEMPERATURE_LIMIT_VIOLATED";
    end
    if max([validRows.temperature_spread_K]) > 5.01
        reasons(end+1,1) = "PUBLIC_TEMPERATURE_SPREAD_LIMIT_VIOLATED";
    end
    if min([validRows.minimum_soc]) < .0795
        reasons(end+1,1) = "PUBLIC_SOC_FLOOR_VIOLATED";
    end
    if min([validRows.minimum_cell_voltage_V]) < 2.749
        reasons(end+1,1) = "PUBLIC_CELL_VOLTAGE_FLOOR_VIOLATED";
    end
    if max([validRows.pump_power_max_W]) > 500.5 || ...
            max([validRows.branch_flow_max_kg_per_s]) > .0601 || ...
            min([validRows.branch_flow_min_kg_per_s]) < -1e-5
        reasons(end+1,1) = "PUBLIC_COOLING_RATING_VIOLATED";
    end
end
if ~G && isempty(reasons)
    reasons(end+1,1) = "GLOBAL_GATE_FAILED";
end
reasons = unique(reasons,"stable");
end

function audit = static_audit(model,def)
required = string({def.outputs.name});
audit = struct( ...
    "required_outputs",required, ...
    "connected_outputs",strings(0,1), ...
    "source_block_types",strings(0,1), ...
    "missing_outputs",strings(0,1), ...
    "duplicate_outputs",strings(0,1), ...
    "output_contract_connected",false, ...
    "precomputed_direct_output_count",0, ...
    "suspicious_callbacks",strings(0,1), ...
    "suspicious_callback_count",0, ...
    "dynamic_block_count",0, ...
    "persistent_chart_count",0, ...
    "dynamic_state_evidence",false);
blocks = find_system(model, ...
    "LookUnderMasks","all", ...
    "FollowLinks","on", ...
    "Type","Block");
if ~isempty(blocks)
    types = string(get_param(blocks,"BlockType"));
    dynamicTypes = [ ...
        "Integrator","DiscreteIntegrator","UnitDelay", ...
        "Memory","Delay","StateSpace","TransferFcn", ...
        "DiscreteStateSpace","DiscreteTransferFcn"];
    audit.dynamic_block_count = nnz(ismember(types,dynamicTypes));
end

try
    root = sfroot;
    charts = find(root,"-isa","Stateflow.EMChart");
    for index = 1:numel(charts)
        chartPath = string(charts(index).Path);
        if startsWith(chartPath,model + "/") && ...
                contains(lower(string(charts(index).Script)),"persistent")
            audit.persistent_chart_count = ...
                audit.persistent_chart_count + 1;
        end
    end
catch
end
audit.dynamic_state_evidence = ...
    audit.dynamic_block_count > 0 || ...
    audit.persistent_chart_count > 0;

callbackNames = [ ...
    "PreLoadFcn","PostLoadFcn","InitFcn", ...
    "StartFcn","StopFcn"];
callbackTokens = [ ...
    "load(","load ","matfile","assignin(", ...
    "evalin(","fromworkspace"];
for callbackIndex = 1:numel(callbackNames)
    try
        callbackText = lower(string(get_param( ...
            model,callbackNames(callbackIndex))));
        if strlength(strtrim(callbackText)) > 0 && ...
                any(contains(callbackText,callbackTokens))
            audit.suspicious_callbacks(end+1,1) = ...
                callbackNames(callbackIndex);
        end
    catch
    end
end
audit.suspicious_callback_count = ...
    numel(audit.suspicious_callbacks);

toWorkspace = find_system(model, ...
    "LookUnderMasks","all", ...
    "FollowLinks","on", ...
    "BlockType","ToWorkspace");
for outputIndex = 1:numel(required)
    matches = strings(0,1);
    for blockIndex = 1:numel(toWorkspace)
        if string(get_param(toWorkspace{blockIndex},"VariableName")) == ...
                required(outputIndex)
            matches(end+1,1) = string(toWorkspace{blockIndex}); %#ok<AGROW>
        end
    end
    if numel(matches) > 1
        audit.duplicate_outputs(end+1,1) = required(outputIndex);
    end
    connected = false;
    sourceType = "";
    for matchIndex = 1:numel(matches)
        ports = get_param(matches(matchIndex),"PortHandles");
        line = get_param(ports.Inport(1),"Line");
        if line > 0
            sourceHandle = get_param(line,"SrcBlockHandle");
            if sourceHandle > 0
                connected = true;
                sourceType = string(get_param( ...
                    sourceHandle,"BlockType"));
                break
            end
        end
    end
    if connected
        audit.connected_outputs(end+1,1) = required(outputIndex);
        audit.source_block_types(end+1,1) = sourceType;
        if has_forbidden_upstream(sourceHandle,8)
            audit.precomputed_direct_output_count = ...
                audit.precomputed_direct_output_count + 1;
        end
    else
        audit.missing_outputs(end+1,1) = required(outputIndex);
    end
end
audit.output_contract_connected = ...
    numel(audit.connected_outputs) == numel(required) && ...
    isempty(audit.duplicate_outputs);
end

function hit = has_forbidden_upstream(blockHandle,remainingDepth)
hit = false;
if blockHandle <= 0, return; end
blockType = string(get_param(blockHandle,"BlockType"));
forbidden = [ ...
    "Constant","FromWorkspace","SignalBuilder", ...
    "FromFile","Playback","RepeatingSequence", ...
    "Clock","DigitalClock","Inport"];
if ismember(blockType,forbidden)
    hit = true;
    return
end
stopping = [ ...
    "SubSystem","S-Function","MATLABSystem", ...
    "Integrator","DiscreteIntegrator","UnitDelay", ...
    "Memory","Delay","StateSpace","TransferFcn", ...
    "DiscreteStateSpace","DiscreteTransferFcn"];
if remainingDepth <= 0 || ismember(blockType,stopping)
    return
end
ports = get_param(blockHandle,"PortHandles");
if ~isfield(ports,"Inport"), return; end
for portIndex = 1:numel(ports.Inport)
    line = get_param(ports.Inport(portIndex),"Line");
    if line <= 0, continue; end
    parentHandle = get_param(line,"SrcBlockHandle");
    if parentHandle > 0 && has_forbidden_upstream( ...
            parentHandle,remainingDepth-1)
        hit = true;
        return
    end
end
end

function expected = request_profile(time,values,def)
expected = zeros(size(time));
stepTime = double(values.load_step_time);
regenTime = double(values.regen_start_time);
demand = double(values.current_demand);
fractions = double(def.public_constants.demand_profile_fractions);
regenDuration = double(def.public_constants.regen_duration_s);
expected(time < stepTime) = fractions(1)*demand;
expected(time >= stepTime & time < regenTime) = ...
    fractions(2)*demand;
expected(time >= regenTime & ...
    time < regenTime+regenDuration) = fractions(3)*demand;
expected(time >= regenTime+regenDuration) = ...
    fractions(4)*demand;
end

function [data,rawSize,timeDimension] = normalize_data( ...
        value,time,expectedChannels)
rawData = double(value.Data);
rawSize = size(rawData);
timeCount = numel(time);
candidates = find(rawSize == timeCount);
assert(numel(rawData) == timeCount*expectedChannels, ...
    "F90_XBATT02_OUTPUT_ELEMENT_COUNT");
assert(isscalar(candidates), ...
    "F90_XBATT02_OUTPUT_TIME_DIMENSION_AMBIGUOUS");
timeDimension = candidates(1);
order = [timeDimension, ...
    setdiff(1:ndims(rawData),timeDimension,"stable")];
data = reshape(permute(rawData,order),timeCount,[]);
end

function [normalizedError,conductance] = thermal_fit( ...
        temperature,qGeneration,qCooling,temperatureRate, ...
        ambientTemperature,thermalCapacity)
residual = zeros(size(temperatureRate));
conductance = zeros(1,size(temperature,2));
for moduleIndex = 1:size(temperature,2)
    ambientDelta = temperature(:,moduleIndex)-ambientTemperature;
    unmodeledLoss = qGeneration(:,moduleIndex) - ...
        qCooling(:,moduleIndex) - ...
        thermalCapacity(moduleIndex)*temperatureRate(:,moduleIndex);
    denominator = sum(ambientDelta.^2);
    if denominator > 1e-12
        conductance(moduleIndex) = max( ...
            sum(ambientDelta.*unmodeledLoss)/denominator,0);
    end
    residual(:,moduleIndex) = ...
        thermalCapacity(moduleIndex)*temperatureRate(:,moduleIndex) - ...
        (qGeneration(:,moduleIndex)-qCooling(:,moduleIndex) - ...
        conductance(moduleIndex)*ambientDelta);
end
scale = max(local_rms(abs(qGeneration)+abs(qCooling)),25);
normalizedError = local_rms(residual)/scale;
end

