function values = nominal_values(def)
values = struct;
for index = 1:numel(def.public_inputs)
    values.(def.public_inputs(index).name) = ...
        def.public_inputs(index).nominal;
end
end

function set_base(values)
names = fieldnames(values);
for index = 1:numel(names)
    assignin("base",names{index},values.(names{index}));
end
end

function snapshot = snapshot_base(names)
snapshot = repmat(struct( ...
    "name","", ...
    "existed",false, ...
    "value",[]),numel(names),1);
for index = 1:numel(names)
    name = names(index);
    snapshot(index).name = name;
    snapshot(index).existed = evalin( ...
        "base","exist('" + name + "','var') == 1");
    if snapshot(index).existed
        snapshot(index).value = evalin("base",name);
    end
end
end

function restore_base(snapshot)
for index = 1:numel(snapshot)
    if snapshot(index).existed
        assignin("base",snapshot(index).name, ...
            snapshot(index).value);
    else
        evalin("base","clear('" + snapshot(index).name + "')");
    end
end
end

function value = positive_correlation(x,y)
x = double(x(:));
y = double(y(:));
valid = isfinite(x) & isfinite(y);
x = x(valid);
y = y(valid);
if numel(x) < 3
    value = 0;
    return
end
x = x-mean(x);
y = y-mean(y);
denominator = sqrt(sum(x.^2)*sum(y.^2));
if denominator <= 1e-12
    value = 0;
else
    value = max(sum(x.*y)/denominator,0);
end
end

function value = quality(metric,good,bad)
if ~isfinite(metric)
    value = 0;
elseif bad <= good
    value = double(metric <= good);
else
    value = clip((bad-metric)/(bad-good));
end
end

function value = quality_high(metric,good,bad)
if ~isfinite(metric)
    value = 0;
elseif good <= bad
    value = double(metric >= good);
else
    value = clip((metric-bad)/(good-bad));
end
end

function value = clip(value)
value = min(max(double(value),0),1);
end

function value = clip_vector(value)
value = min(max(double(value),0),1);
end

function value = local_rms(data)
value = sqrt(mean(double(data).^2,"all"));
end

function values = struct_numeric(input)
names = fieldnames(input);
values = [];
for index = 1:numel(names)
    value = input.(names{index});
    if isnumeric(value) || islogical(value)
        values = [values,double(value(:).')]; %#ok<AGROW>
    end
end
end

